{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"pygments_lexer":"ipython3","nbconvert_exporter":"python","version":"3.6.4","file_extension":".py","codemirror_mode":{"name":"ipython","version":3},"name":"python","mimetype":"text/x-python"},"kaggle":{"accelerator":"none","dataSources":[],"isInternetEnabled":true,"language":"python","sourceType":"script","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# %% [code]\n# This Python 3 environment comes with many helpful analytics libraries installed\n# It is defined by the kaggle/python Docker image: https://github.com/kaggle/docker-python\n# For example, here's several helpful packages to load\n\nimport numpy as np # linear algebra\nimport pandas as pd # data processing, CSV file I/O (e.g. pd.read_csv)\n\n# Input data files are available in the read-only \"../input/\" directory\n# For example, running this (by clicking run or pressing Shift+Enter) will list all files under the input directory\n\nimport os\nfor dirname, _, filenames in os.walk('/kaggle/input'):\n    for filename in filenames:\n        print(os.path.join(dirname, filename))\n\n# You can write up to 20GB to the current directory (/kaggle/working/) that gets preserved as output when you create a version using \"Save & Run All\" \n# You can also write temporary files to /kaggle/temp/, but they won't be saved outside of the current session\n\n# %% [code]\nimport streamlit as st\nimport pandas as pd\nimport numpy as np\nimport joblib\n# Load saved model and scaler\nmodel  = joblib.load('hotel_model.pkl')\nscaler = joblib.load('scaler.pkl')\n\nst.set_page_config(page_title='Hotel Cancellation Predictor',\n                   page_icon='🏨', layout='centered')\n\nst.title('🏨 Hotel Booking Cancellation Predictor')\nst.markdown('Fill in the booking details to predict cancellation risk.')\n\ncol1, col2 = st.columns(2)\nwith col1:\n    lead_time      = st.number_input('Lead Time (days)', 0, 700, 50)\n    adr            = st.number_input('Average Daily Rate ($)', 0.0, 600.0, 100.0)\n    total_stay     = st.number_input('Total Stay (nights)', 1, 30, 3)\n    adults         = st.number_input('Adults', 1, 10, 2)\n\nwith col2:\n    hotel_type     = st.selectbox('Hotel Type', ['City Hotel', 'Resort Hotel'])\n    deposit_type   = st.selectbox('Deposit Type', ['No Deposit','Non Refund','Refundable'])\n    prev_cancel    = st.number_input('Previous Cancellations', 0, 20, 0)\n    booking_changes= st.number_input('Booking Changes', 0, 20, 0)\n\nhotel_enc   = 0 if hotel_type == 'City Hotel' else 1\ndeposit_enc = {'No Deposit':0,'Non Refund':1,'Refundable':2}[deposit_type]\nif st.button('Predict Cancellation Risk', type='primary'):\n    input_data = np.array([[lead_time, adr, total_stay, adults,\n                            hotel_enc, deposit_enc,\n                            prev_cancel, booking_changes,\n                            adults, total_stay,\n                            adr * total_stay, 0]])\n   # Note: in real app, match all columns your model was trained on\n    # For demo, we feed available features\n    try:\n        scaled = scaler.transform(input_data)\n        pred   = model.predict(scaled)[0]\n        prob   = model.predict_proba(scaled)[0][1]\n        if pred == 1:\n            st.error(f'⚠️ High Risk of Cancellation — {prob*100:.1f}% probability')\n        else:\n            st.success(f'✅ Low Risk of Cancellation — {prob*100:.1f}% probability')\n\n        st.metric('Cancellation Probability', f'{prob*100:.1f}%')\n    except Exception as e:\n        st.warning(f\"Ensure your model columns match. Error: {e}\")","metadata":{"_uuid":"4f3da6cf-c4f9-4b13-b5e8-109c9809d83d","_cell_guid":"60ef3553-fa30-4668-b91b-19f45162f819","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false}},"outputs":[],"execution_count":null}]}